# Get non-empty, non-comment lines
lines = [line.strip() for line in student_code.split('\n') if line.strip() and not line.strip().startswith('#')]

# Task 1: Check imports
if not any('import requests' in line for line in lines):
    raise AssertionError('Task 1: Missing "import requests"')
if not any('JSONDecodeError' in line and 'import' in line for line in lines):
    raise AssertionError('Task 1: Missing import of JSONDecodeError')

# Task 3: Check POST request
if not any('response' in line and 'requests.post' in line and 'json=' in line for line in lines):
    raise AssertionError('Task 3: response should use requests.post() with json= parameter')
if not any('new_comment' in line for line in lines if 'json=' in line):
    raise AssertionError('Task 3: Should send new_comment as JSON data')

# Task 4: Check try block and JSON parsing
if 'try:' not in student_code:
    raise AssertionError('Task 4: Missing try block')
if not any('response_data' in line and 'response.json()' in line for line in lines):
    raise AssertionError('Task 4: Should parse JSON with response.json()')

# Task 5: Check status code check
if '200' not in student_code or '201' not in student_code:
    raise AssertionError('Task 5: Should check for status codes 200 and 201')
if not any('print' in line and 'response_data' in line for line in lines):
    raise AssertionError('Task 5: Should print the response data')

# Task 6: Check else clause
if 'else:' not in student_code:
    raise AssertionError('Task 6: Missing else clause')
if not any('Request failed' in line and 'status_code' in line for line in lines):
    raise AssertionError('Task 6: Should print failure message with status code')

# Task 7: Check except block
if 'except JSONDecodeError:' not in student_code:
    raise AssertionError('Task 7: Missing except JSONDecodeError block')
if not any('Invalid JSON' in line for line in lines):
    raise AssertionError('Task 7: Should print "Error: Invalid JSON response"')

print('TEST_PASSED')
